require 'benchmark'

def longest_palindromic_substring(str)
  res = ""
  sub_str = ""
  len = str.length
  seen = {}

  len.times do |idx|
    str[0..str.length-idx].length.times do |s_idx|
      sub_str = str[idx..s_idx]
      if !seen[sub_str] && sub_str.length > res.length && is_palindrome?(sub_str)
        res = sub_str
      end
      seen[sub_str] = true
    end
  end

  res
end

def is_palindrome?(str)
  str.eql?(str.reverse)
end



p longest_palindromic_substring("qwertyytrewqasd")
p longest_palindromic_substring("babbad")
# p longest_palindromic_substring("")


c_sol = Benchmark.measure do

puts longest_palindromic_substring("")
puts longest_palindromic_substring("")
end

p c_sol.total